package com.ultimatesurvival.client.rig;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.ultimatesurvival.UltimateSurvival;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/** A mob model as generated by tools/usm_gen/rig.py: bones with boxes, plus declarative animation rules. */
public final class RigDef {
	public record Cube(int u, int v, float x, float y, float z, int w, int h, int d, float inflate, boolean mirror) {
	}

	public record Bone(String name, String parent, float px, float py, float pz, float rx, float ry, float rz, List<Cube> cubes) {
	}

	/** Animation rule; values are added to the bone's rest pose (see rig.py for the vocabulary). */
	public record Rule(String bone, String when, String axis, String fn, double speed, double amp, double phase, double off,
			double value, double mul, float[][] keys) {
	}

	public final String id;
	public final int texW;
	public final int texH;
	public final List<Bone> bones = new ArrayList<>();
	public final List<Rule> rules = new ArrayList<>();

	private RigDef(JsonObject o) {
		this.id = o.get("id").getAsString();
		JsonArray tex = o.getAsJsonArray("tex");
		this.texW = tex.get(0).getAsInt();
		this.texH = tex.get(1).getAsInt();
		for (JsonElement e : o.getAsJsonArray("bones")) {
			JsonObject b = e.getAsJsonObject();
			JsonArray pivot = b.getAsJsonArray("pivot");
			JsonArray rot = b.getAsJsonArray("rot");
			List<Cube> cubes = new ArrayList<>();
			for (JsonElement ce : b.getAsJsonArray("cubes")) {
				JsonObject c = ce.getAsJsonObject();
				JsonArray uv = c.getAsJsonArray("uv");
				JsonArray org = c.getAsJsonArray("o");
				JsonArray size = c.getAsJsonArray("s");
				cubes.add(new Cube(uv.get(0).getAsInt(), uv.get(1).getAsInt(), org.get(0).getAsFloat(), org.get(1).getAsFloat(), org.get(2).getAsFloat(),
						size.get(0).getAsInt(), size.get(1).getAsInt(), size.get(2).getAsInt(), c.get("inflate").getAsFloat(), c.get("mirror").getAsBoolean()));
			}
			bones.add(new Bone(b.get("name").getAsString(), b.get("parent").isJsonNull() ? null : b.get("parent").getAsString(),
					pivot.get(0).getAsFloat(), pivot.get(1).getAsFloat(), pivot.get(2).getAsFloat(),
					rot.get(0).getAsFloat(), rot.get(1).getAsFloat(), rot.get(2).getAsFloat(), cubes));
		}
		for (JsonElement e : o.getAsJsonArray("rules")) {
			JsonObject r = e.getAsJsonObject();
			float[][] keys = null;
			if (r.has("keys")) {
				JsonArray ks = r.getAsJsonArray("keys");
				keys = new float[ks.size()][2];
				for (int i = 0; i < ks.size(); i++) {
					keys[i][0] = ks.get(i).getAsJsonArray().get(0).getAsFloat();
					keys[i][1] = ks.get(i).getAsJsonArray().get(1).getAsFloat();
				}
			}
			rules.add(new Rule(r.get("bone").getAsString(), r.get("when").getAsString(), r.get("axis").getAsString(), r.get("fn").getAsString(),
					d(r, "speed", 0), d(r, "amp", 0), d(r, "phase", 0), d(r, "off", 0), d(r, "value", 0), d(r, "mul", 1), keys));
		}
	}

	private static double d(JsonObject o, String k, double def) {
		return o.has(k) ? o.get(k).getAsDouble() : def;
	}

	public static RigDef load(String id) {
		String path = "/assets/" + UltimateSurvival.MOD_ID + "/usm_rigs/" + id + ".json";
		try (InputStream in = RigDef.class.getResourceAsStream(path)) {
			if (in == null) {
				throw new IllegalStateException("missing rig " + path + " - run python tools/gen_all.py");
			}
			return new RigDef(JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject());
		} catch (IOException e) {
			throw new IllegalStateException("cannot read rig " + id, e);
		}
	}
}
